from typing import Type, Any, Optional
import rclpy
from rclpy.node import Node as ROS2BaseNode
from ..logger.logger import logger
import time


class ROS2Client:
    def __init__(
        self,
        node: ROS2BaseNode,
        srv_type: Type,
        service: str,
        qos_profile: int = 10,
        **kwargs,
    ):
        """
        创建ROS2服务客户端

        Args:
            node: ROS2BaseNode实例
            srv_type: 服务类型
            service: 服务名称
            qos_profile: QoS配置
            **kwargs: 其他参数传递给create_client
        """
        self._node = node
        self._srv_type = srv_type
        self._service = service
        self._client = node.create_client(srv_type, service, **kwargs)

    def _is_node_spinning(self) -> bool:
        """
        检查节点是否有executor（可能正在被spin）

        Returns:
            True表示节点已添加到executor，False表示没有
        """
        try:
            executor = getattr(self._node, "executor", None)
            return executor is not None
        except Exception:
            return False

    def call(self, request: Any, timeout_sec: Optional[float] = None) -> Any:
        """
        同步调用服务

        Args:
            request: 服务请求对象
            timeout_sec: 超时时间（秒），None表示无限等待

        Returns:
            服务响应对象，超时返回None
        """
        future = self._client.call_async(request)
        try:
            if self._is_node_spinning():
                # 节点正在被spin，等待future完成
                start_time = time.time()
                while not future.done():
                    if timeout_sec is not None:
                        elapsed = time.time() - start_time
                        if elapsed >= timeout_sec:
                            logger.error("Service call timeout")
                            return None
                    time.sleep(0.001)  # 短暂休眠避免CPU占用过高
                return future.result()
            else:
                # 节点没有被spin，使用 spin_until_future_complete
                rclpy.spin_until_future_complete(
                    self._node, future, timeout_sec=timeout_sec
                )
                if future.done():
                    return future.result()
                else:
                    logger.error("Service call timeout")
                    return None
        except TimeoutError:
            logger.error("Service call timeout")
            return None
        except Exception as e:
            logger.error(f"Service call failed: {e}")
            return None

    def call_async(self, request: Any):
        """
        异步调用服务

        Args:
            request: 服务请求对象

        Returns:
            Future对象
        """
        return self._client.call_async(request)

    def wait_for_service(self, timeout_sec: Optional[float] = None) -> bool:
        """
        等待服务可用

        Args:
            timeout_sec: 超时时间（秒），None表示无限等待

        Returns:
            服务是否可用
        """
        return self._client.wait_for_service(timeout_sec=timeout_sec)

    @property
    def service(self) -> str:
        """获取服务名称"""
        return self._service

    @property
    def srv_type(self) -> Type:
        """获取服务类型"""
        return self._srv_type

    def destroy(self):
        """销毁客户端"""
        self._node.destroy_client(self._client)
